def next_smallest_palindrome(num):
    if num < 0:
        raise ValueError("Input must be a non-negative integer")

    original_num = num + 1
    while True:
        str_num = str(original_num)
        length = len(str_num)
        half = (length + 1) // 2
        left_half = int(str_num[:half])

        if length % 2 == 0:
            palindrome = left_half * 10 ** (half) + reversed(left_half)
        else:
            palindrome = left_half * 10 ** (half - 1) + int(str(left_half)[::-1])

        if palindrome > num:
            return palindrome
        original_num += 1

def reversed(num):
    return int(str(num)[::-1])
