def find_Index(n):
    if n < 1:
        return -1  # invalid input case

    lower_bound = 10 ** (n - 1)
    upper_bound = 10 ** n - 1
    i = 1
    triangular_number = 0

    while True:
        triangular_number = i * (i + 1) // 2
        if lower_bound <= triangular_number <= upper_bound:
            return i
        elif triangular_number > upper_bound:
            return i - 1  # because previous one is the smallest triangular number with n digits
        else:
            i += 1
